begin
             if at(74,19) then
             if wantenter('WATER FIELD') then begin
                with party do begin
                   map := 10; xaxis := 25; yaxis := 70;
                end;
                load;
                if party.etc[38] and bit4 > 0 then map[40,56] := 44;
             end;
             if at(23,62) then
             if wantenter('NOTICE') then begin
                with party do begin
                   map := 17; xaxis := 56; yaxis := 94;
                end;
                load;
             end;
             if at(96,42) then
             if wantenter('LOCKUP') then begin
                with party do begin
                   map := 18; xaxis := 25; yaxis := 94;
                end;
                load;
             end;
          end

if wantenter('WIVERN') then begin
              with party do begin
                 map := 16; xaxis := 20; yaxis := 9;
              end;
              load;
           end

begin
                 Print(7,'');
                 if at(68,47) then Print(15,'    하! 하! 하!  너는 우리에게 속았다');
                 if at(58,53) then begin
                    Print(10,'      이 게임을 만든 사람');
                    Print(15,'  : 동아 대학교 전기 공학과');
                    Print(15,'        92 학번  안 영기');
                 end;
                 if at(51,30) then begin
                    Print(15,'       오른쪽 : Hidra 의 보물창고');
                    Print(15,'       왼  쪽 : Hidra 가 있는 방');
                 end;
                 if at(66,13) then Print(15,'     일찌감치 이 곳 탐험을 포기해라');
                 if at(9,28) then Print(15,'         위쪽이 진짜 보물창고임');
              end

begin
              if y = 46 then begin
                 y := 50;
                 scroll(TRUE);
              end;
              if y = 49 then begin
                 y := 45;
                 scroll(TRUE);
              end;
              if y = 71 then begin
                 if wantexit then begin
                    with party do begin
                       xaxis := 74; yaxis := 20; map := 3;
                    end;
                    load;
                 end
                 else begin
                    dec(y); scroll(TRUE);
                 end;
              end;
           end

begin
              Clear;
              if y = 95 then
              if wantexit then begin
                 with party do begin
                    xaxis := 23; yaxis := 63; map := 3;
                 end;
                 load; scroll(TRUE);
              end
              else begin
                 dec(y); scroll(TRUE);
              end;
              if y = 80 then y := 6;
              if y = 44 then for i := 67 to 69 do begin
                 map[i,44] := 44; map[i,38] := 52;
              end;
              if on(75,52) and (party.etc[38] and bit2 = 1) then exit;
              if on(75,52) and (party.etc[38] and bit1 = 1)
              and (party.etc[5]>0) then begin
                 Print(7,' 다시 생각해보니 나도 직접 Necromancer에 도');
                 Print(7,'전하고픈 마음이 생겼소.  비록 육체적인 힘은');
                 Print(7,'전혀없는 영이지만 당신들과 같이 모험을 하고');
                 Print(7,'싶소. 당신들의 생각은 어떻소.');
                 m[0] := '';
                 m[1] := '당신의 제의을 받아 들이겠소';
                 m[2] := '당신이 전해준 마법만으로도 족하오';
                 k := select(140,2,2,FALSE,TRUE);
                 if k = 0 then exit;
                 if k = 2 then begin
                    asyouwish; exit;
                 end;
                 if k = 1 then begin
                    k := ReturnJoinMember;
                    if k = 1 then begin
                       asyouwish; exit;
                    end;
                    join(55,k);
                    with player[k] do begin
                       name := 'Red Antares';
                       class := 9;
                       weapon := 0;
                       shield := 0;
                       armor := 0;
                       wea_power := 0;
                       shi_power := 0;
                       arm_power := 0;
                       ac := 0;
                       hp := 0;
                       resistance := 15;
                       endurance := 10;
                    end;
                    Display_Condition;
                 end;
                 party.etc[38] := party.etc[38] or bit2;
                 exit;
              end;
              if on(75,52) and (party.etc[38] and bit1 = 1)
              and (party.etc[38] and bit2 = 0) then
                 talk('나는 다시 영혼의 세계로 돌아가야 겠소.');
              if on(75,52) and (party.etc[38] and bit1 = 0) then begin
                 for j := 47 to 57 do
                 for i := 71 to 82 do
                 if map[i,j] = 40 then map[i,j] := 50;
                 Silent_Scroll;
                 talk('갑자기 주위가 용암으로 변하면서 한 영혼이 당신앞에 나타났다.');
                 cPrint(7,11,' 나는 고대의 강력한 마법사 였던 ','Red Antares','');
                 cPrint(7,11,'','의 영','이오.');
                 Print(7,' 한때,  나는 이 세계의 모든 지역을 통괄하는');
                 Print(7,'마법을 가지고 이 세계를 통치했지만  내가 죽');
                 Print(7,'고난 뒤로는 여러 지역으로  나의 마법이 분산');
                 Print(7,'되어 제대로 힘을 발휘하지 못하는것 같소. 당');
                 Print(7,'신들이 Necromancer에 대항하려 한다는걸 알고');
                 Print(7,'있소. 나는 그가 이 동굴을 요새화  시킬때 이');
                 Print(7,'미 그의 마법 능력을 지켜 보았기 때문에 그의');
                 Print(7,'능력을 알수 있었소. 그러나 그의 능력에 비교');
                 Print(7,'해볼때 당신들의 마법 능력은 상당히 저조하오');
                 Print(7,'. 그래서 당신들을 위해 나의 마법중 "간접 공');
                 Print(7,'격"이란 기법을 전해 주겠소.');
                 Print(7,' 만약 당신들의 마법 능력이 도달한다면  다음');
                 Print(7,'의 마법을 사용할수 있을 것이오.');
                 Print(7,''); talk('');
                 Print(15,'1.     독      - 적을 중독 시킴');
                 Print(15,'2. 기술 무력화 - 적의 특수 공격 능력 제거');
                 Print(15,'3. 방어 무력화 - 적의 방어력 감소');
                 Print(15,'4. 능력   저하 - 적의 모든 능력 감소');
                 Print(15,'5. 마법   불능 - 적의 마법 능력 제거');
                 Print(15,'6. 탈   초인화 - 적의 초자연력 제거');
                 PressAnyKey;
                 Print(7,' 이 여섯가지의 마법은 사용하기 까다롭고  직');
                 Print(7,'접적인 공격은 아니지만 큰 도움을 줄것이오.');
                 Print(7,'하지만, 사실  이 마법들을 모두 동원하더라도');
                 Print(7,'Necromancer를 만나기 조차 어려울 것이오. 그');
                 Print(7,'래서 당신들은 초자연력 또한 익혀야만 그에게');
                 talk('대항할수 있을 것이오.');
                 party.etc[38] := party.etc[38] or bit1;
              end;
              if x = 72 then begin
                 for j := 19 to 21 do map[72,j] := 44;
                 y := y - 7;
              end;
              if y = 38 then begin
                 for i := 67 to 69 do begin
                    map[i,38] := 44; map[i,44] := 52;
                 end;
                 x := 56; y := 93;
              end;
              if (x = 22) and (party.etc[15] < 2) then begin
                 if party.etc[1] = 0 then begin
                    party.etc[1] := 1;
                    scroll(true);
                 end;
                 Print(11,'당신은 보스인 Hidra를 만났다.');
                 for i := 2 to 3 do begin
                    putimage(i*20-20,100,chara^[36],andput);
                    putimage(i*20-20,100,chara^[8],orput);
                    putimage(i*20,100,chara^[40],andput);
                    putimage(i*20,100,chara^[12],orput);
                    delay(1000);
                 end;
                 for i := 2 to 4 do begin
                    putimage(i*20-20,80,chara^[36],andput);
                    putimage(i*20-20,80,chara^[8],orput);
                    putimage(i*20,80,chara^[40],andput);
                    putimage(i*20,80,chara^[12],orput);
                    putimage(i*20-20,120,chara^[36],andput);
                    putimage(i*20-20,120,chara^[8],orput);
                    putimage(i*20,120,chara^[40],andput);
                    putimage(i*20,120,chara^[12],orput);
                    delay(700);
                 end;
                 putimage(60,100,chara^[36],andput);
                 putimage(60,100,chara^[8],orput);
                 putimage(80,100,chara^[40],andput);
                 putimage(80,100,chara^[12],orput);
                 PressAnyKey;
                 enemynumber := 3;
                 for i := 1 to 3 do begin
                    joinenemy(i,49);
                    with enemy[i] do begin
                       name := 'Hidra''s Head '+chr(48+i);
                       level := 8;
                       E_number := 34;
                    end;
                    enemy[2].level := 10;
                    enemy[2].E_number := 39;
                 end;
                 Displayenemies(TRUE);
                 BattleMode(TRUE);
                 if party.etc[6] = 255 then exit;
                 if party.etc[6] = 0 then begin
                    Clear;
                    Print(15,'당신들은 Hidra를 물리쳤다.');
                    Print(11,'그리고 당신은 이 임무에 성공했다.');
                    Print(15,'다시 WATER FIELD 의 군주에게로 돌아가라.');
                    PressAnyKey;
                    party.etc[15] := 2;
                    x := 56; y := 93;
                    scroll(TRUE);
                 end
                 else begin
                    inc(x); scroll(TRUE);
                 end;
              end;
           end

begin
      if at(36,32) or at(38,33) or at(39,35) then train_center;
      if at(17,57) or at(12,59) or at(11,55) then grocery;
      if at(11,30) or at(11,32) or at(13,34) then weapon_shop;
      if at(33,60) or at(35,54) or at(41,58) then hospital;
      if at(11,16) then
         talk('NOTICE 동굴의 Hidra는 머리가 셋이나 달렸다더군요.');
      if at(14,18) then
         talk('NOTICE 동굴은 혼란스러운 미로라서 항상 주위를 염두에 두셔야 합니다.');
      if at(24,22) then
         talk('LOCKUP 동굴은 미로로 구성된 동굴이오.');
      if at(27,22) then
         talk('LOCKUP 속에 Minotaur는 Necromancer의 부하는 아닙니다.');
      if at(24,69) then begin
         Print(7,' LOCKUP 의 보스인 Huge Dragon은 아주 거대한');
         Print(7,'용이라는데,  그것의 꼬리 또한 강력한 무기라');
         Print(7,'서 조심해야 할것이오.');
         PressAnyKey;
      end;
      if at(37,16) then begin
         Print(7,' 고르곤 세자매의 힘은 Necromancer의 힘과 필');
         Print(7,'적하지만 중대한 약점이 하나 있소.');
         PressAnyKey;
      end;
      if at(40,18) then
         talk('Stheno 와 Euryale는 거의 불멸의 생명체 입니다.');
      if at(40,56) then begin
         hany := 20;
         Print(7,' 나는 LORE 특공대의 대장인 Lore Hunter 라고');
         Print(7,'하오. 여기서의 적들과는, 이제 대항하기가 혼');
         Print(7,'자서는 무리라고 판단했소. 그래서, 나는 여태');
         Print(7,'껏 여기서 새로운 영웅들을 기다리고 있었소.');
         Print(7,' 내가 당신의 일행에 끼게 되는걸 어떻게 생각');
         Print(7,'하오 ?');
         m[0] := '';
         m[1] := '우리도 그러기를 바라오';
         m[2] := '몸이 완전히 회복될때까지 기다리시오';
         k := select(145,2,2,FALSE,TRUE);
         if k = 2 then asyouwish;
         if k <> 1 then exit;
         k := ReturnJoinMember;
         if k = 1 then exit;
         join(39,k);
         with player[k] do begin
            name := 'Lore Hunter';
            class := 7;
            weapon := 5;
            shield := 2;
            armor := 1;
            wea_power := 15;
            shi_power := 2;
            arm_power := 2;
            ac := 4;
         end;
         Display_Condition;
         map[40,56] := 44;
         Silent_Scroll;
         party.etc[38] := party.etc[38] or bit4;
      end;
      if at(25,18) then
      case party.etc[15] of
         0 : begin
          Print(7,' 여기는 WATER FIELD 라는 성이오.  이곳이 당');
          Print(7,'신이 마지막으로 거칠 우리편의 성이오.');
          Print(7,' 차원의 틈을 통해 Necromancer가 내려 오던날');
          Print(7,'이 대륙은 거의 전부가 바다로 가라않았소. 하');
          Print(7,'지만  그때에 살아 남은 사람들은 아직 가라않');
          Print(7,'지 않은 이곳에 찾아와서 이 성을 건립했소.그');
          Print(7,'리고는  공이 컸던 나를 왕으로 추대했던 것이');
          Print(7,'오.');
          Print(7,' 당신도 생각하고 있다시피 이 대륙은 거의 물');
          Print(7,'로 덮혀있소.  하지만 이곳처럼 물이 차지않은');
          Print(7,'두곳에 Necromancer 는 이미 이 대륙의 지배를');
          Print(7,'위한 동굴을 만들었소. 그 두곳의 적들은 여타');
          Print(7,'의 대륙과는 비교가 안될 정도의  거대한 적들');
          Print(7,'이 많이 있소.');
          Print(7,' 우리로서는 더 이상 손을 쓸수가 없소.  이곳');
          Print(7,'사람들의 마지막 희망인  이 곳이 적들에게 점');
          Print(7,'령된다면 WIVERN 동굴로 이어지는 워터 게이트');
          Print(7,'를 통해 다른 대륙도 하나둘씩  점령되어 갈것');
          Print(7,'이오.');
          talk('');
          inc(party.etc[15]);
             end;
         1 : begin
          Print(7,' 먼저,  여기서 남서쪽의 어느 섬에 있는 동굴');
          Print(7,'인 NOTICE에 가서 보스인 Hidra를 물리쳐 주십');
          Print(7,'시오.');
          PressAnyKey;
             end;
         2 : begin
          Print(7,'Hidra를 물리치다니 ... 대단한 능력이오.');
          Print(11,'[ EXP + 150000 ]');
          Print(7,'');
          for i := 1 to 6 do if player[i].name <> '' then
             player[i].experience := player[i].experience + 150000;
          Print(7,'이제는 소문으로만 듣던 당신들의 능력을 믿을');
          Print(7,'수 있겠소.');
          PressAnyKey;
          inc(party.etc[15]);
             end;
         3 : begin
          Print(7,' 이번에는  대륙의 동쪽에 있는 LOCKUP 동굴속');
          Print(7,'의 Huge Dragon을 물리쳐 주시오.');
          PressAnyKey;
             end;
         4 : begin
          Print(7,'역시 위대한 영웅이오 !!');
          Print(11,'[ EXP + 300000 ]');
          Print(7,'');
          for i := 1 to 6 do if player[i].name <> '' then
             player[i].experience := player[i].experience + 300000;
          Print(7,'여기에 Swamp Key 가 있소.');
          PressAnyKey;
          inc(party.etc[15]);
             end;
         5 : begin
          Print(7,' Swamp Key 는 GAIA TERRA 의 스왐프 게이트를');
          Print(7,'여는데 사용되오.  거기서 늪의 대륙으로 가시');
          Print(7,'오. 늪의 대륙은 완전한 적들의 소굴이므로 매');
          Print(7,'우 주의하시오.');
          PressAnyKey;
             end;
      end;
          end
